"""Explicit scenarios for execution plans, partitions and joins. No DB writes.
--check compares authored output; keep stable IDs and old Shuffle tasks.
"""
from pathlib import Path
import json
import sys

ROOT = Path(__file__).resolve().parents[1] / 'src/content'
GUIDES = json.loads((ROOT/'standardGuides.json').read_text(encoding='utf-8'))
DELAYED = json.loads((ROOT/'delayedChecks.json').read_text(encoding='utf-8'))
DELAYED['items'] = [i for i in DELAYED['items'] if not i['slug'].startswith(('l4-','l5-','l6-'))]
BASE = 'https://spark.apache.org/docs/3.5.7/'
lessons = {}

def lesson(slug,title,mission,correction,source='sql-performance-tuning.html'):
    global current
    current=dict(slug=slug,version=1,title=title,mission=mission,correction=correction,source=BASE+source,
                 next='用自己的话解释判断，再进入下一课。章末可下载独立任务实作；互动记录不替代正式检验。',tasks=[])
    lessons[slug]=current
    GUIDES['lessons'][slug]=dict(title=title,sections=[],sources=[dict(title='Spark 3.5.7 官方说明',url=BASE+source)])

def q(key,title,intro,code,prompt,choices,correct,feedback,principle,boundary):
    ident=current['slug']+'/'+key
    field=dict(id='answer',label='你的判断',correctOptionId=f'o{correct}',options=[dict(id=f'o{i}',text=text,feedback=feedback[i]) for i,text in enumerate(choices)])
    t=dict(id=ident,knowledgeIds=[ident],title=title,intro=intro,code=code,prompt=prompt,fields=[field],insight=principle,ability=title,
           reading=dict(id=ident+'/reading',title=title,sectionTitle='先用人话理解',startMarker='【先用人话理解】',endMarker='【一个直观的心智模型】',connection=principle,boundary=boundary,
                        caution='这是保留的历史讲义。固定 Shuffle/Stage 数、固定选型和绝对性能结论请以当前标准讲解的条件与边界为准。'))
    current['tasks'].append(t)
    GUIDES['lessons'][current['slug']]['sections'].append(dict(id=ident,title=title,body=principle,boundary=boundary))
    return t

def follow(t,key,title,code,prompt,choices,correct,feedback,delayed_code,delayed_prompt,delayed_choices,delayed_correct,explanation):
    t['remediation']=dict(id=current['slug']+'/'+key,knowledgeId=t['knowledgeIds'][0],title=title,intro='换一个情境，验证同一个判断。',code=code,prompt=prompt,
        field=dict(id='answer',label='变式判断',correctOptionId=f'r{correct}',options=[dict(id=f'r{i}',text=text,feedback=feedback[i]) for i,text in enumerate(choices)]),insight=explanation)
    DELAYED['items'].append(dict(id=current['slug']+'/'+key+'-delayed-v1',slug=current['slug'],taskId=t['id'],knowledgeId=t['knowledgeIds'][0],title=title,
        code=delayed_code,prompt=delayed_prompt,options=[dict(id=f'd{i}',text=text) for i,text in enumerate(delayed_choices)],correctOptionId=f'd{delayed_correct}',explanation=explanation))

lesson('l4-why-explain','日报变慢，先找一条证据','别先猜内存或改参数。从查询计划提出可以验证的假设。','explain 不是计时器，也不直接给出完整运行瓶颈。计划可能需要分析/元数据工作；实际读量、等待与最终 AQE 行为要结合执行指标。','sql-ref-syntax-qry-explain.html')
q('evidence','只有总耗时，先别开药方','两次日报各跑了 20 秒和 60 秒，尚未控制输入与资源。','# 教学情境\n原来 20s，现在 60s；没有计划或 UI 指标。','第一步更合理的是？',['先把 Executor 内存翻倍','收集计划、数据规模与运行指标，形成假设','认定 SQL 语法变长导致变慢'],1,['内存是否瓶颈还没有证据。','对，先定位变化发生在哪一段。','文本长度不是可靠的成本证据。'],'诊断从需求、执行计划和指标出发。先描述问题，再决定改什么。','耗时对比还需控制缓存、资源和输入等条件。')
t=q('plan-not-timer','计划能回答什么','一份计划中出现 Sort 和 Exchange。','# 简化教学计划\nSort [total DESC]\n+- Exchange rangepartitioning(total, 8)\n   +- Scan source','仅凭这段能确定什么？',['排序/交换值得进一步检查','Exchange 恰好耗时 30 秒','瓶颈必定在网络'],0,['对，节点提供检查方向。','计划文本没有这项实测耗时。','还缺交换量、磁盘、等待等证据。'],'计划说明如何执行，不直接提供每个节点的实际耗时。','示例是简化片段，不是一次真实运行报告。')
follow(t,'timer-transfer','计划不是秒表','# 教学片段：HashAggregate -> Exchange -> Scan','看到 Exchange，接下来应该？',['先认定磁盘坏了','查交换量、task 分布和运行时间','按节点数算秒数'],1,['还没有硬件故障证据。','对，用指标验证怀疑。','节点数不能换算秒数。'],'# 新片段：BroadcastExchange -> Scan dim','能仅凭它得出广播实际耗时吗？',['能，固定 1 秒','能，由行数直接推算','不能，还需运行指标'],2,'计划是执行结构证据，实际耗时必须测量。')
q('hypothesis','从宽扫描提出可验证假设','报表只输出地区与金额，源文件还有大量描述字段。','# 教学片段\nReadSchema: region, amount, long_description','应该优先验证什么？',['是否可只读取需要的列，并对照读量','必须把所有列缓存','先删除源文件中的描述字段'],0,['对，先验证裁剪是否生效及收益。','缓存全部字段可能放大资源开销。','不应破坏源数据来做第一次验证。'],'减少不需要的读取是可检验的假设；确认列裁剪和实际读取量再判断收益。','不同数据源的裁剪能力不同，计划中的字段列表只是证据之一。')
q('compare','结果也要一起验收','优化后 40 秒变 20 秒，但输出总额少了一半。','# 对比：耗时下降；业务结果发生变化。','这次算优化成功吗？',['算，只要更快','不算，先验证等价结果和测试条件','算，因为行数更少'],1,['更快的错误答案不满足需求。','对，正确性是前提。','减少结果可能是错误过滤造成。'],'性能变更要同时验证结果、计划、指标和测试条件。','小样本收益不能直接外推生产规模。')

lesson('l4-logical-vs-physical','同一需求，执行路线可以不同','分开看要算什么与怎样计算。','逻辑计划也有解析、分析和优化阶段；物理计划不是源码逐行翻译，AQE 还可能在运行后调整。','sql-ref-syntax-qry-explain.html')
q('meaning','先说需求，再说机器怎么做','需求是每地区销售合计。','orders.groupBy("region").sum("amount")','“按地区求和”首先描述哪一层？',['业务与逻辑计算需求','网络连接数','物理机器编号'],0,['对，它还没有指定具体物理聚合路线。','语句没有给出网络连接数。','逻辑字段不对应机器编号。'],'逻辑计划描述关系与表达式，物理计划选择满足需求的执行算子。','同一语义可能存在多个可行物理实现。')
t=q('route','同样连接，为什么路线不同','同一等值连接，维表规模与统计发生变化。','# 简化教学对照\n方案 A: BroadcastHashJoin\n方案 B: SortMergeJoin','两种节点说明什么？',['业务连接条件必定不同','可能是同一逻辑连接的不同物理实现','两者输出字段必定不同'],1,['节点名不同并不证明条件不同。','对，选型受数据与配置影响。','字段也取决于投影与连接条件。'],'比较计划时先确认语义，再解释物理选型及其条件。','不要只凭算子名字宣称结果相同或某个一定更快。')
follow(t,'route-transfer','需求和路线分层','# 对照：同样 SELECT k,SUM(v) GROUP BY k\n计划分别使用不同聚合实现。','应怎样解释？',['可能同需求不同实现，仍需核对语义与结果','一定是一份计划错了','一定是不同业务'],0,['对，物理实现可以变化。','不能仅凭不同就判错。','逻辑需求已明确相同。'],'# 某等值连接初始 SMJ，执行后 AQE 改为 BHJ。','这必然代表业务需求变了吗？',['是','否，可能调整物理路线','必须重新定义字段'],1,'逻辑语义与物理路线应分开；路线变化还要核对适用条件与结果。')
q('analysis','字段不存在在哪一步暴露','查询引用 amuont，实际字段为 amount。','SELECT amuont FROM orders','优化前应先解决什么？',['把 Shuffle 分区加倍','字段解析与分析错误','给结果排序'],1,['参数不能补出缺失字段。','对，先让名字和类型可解析。','排序不解决字段拼错。'],'分析阶段解析关系、字段与类型；未解决的语义错误不能靠物理调参修复。','错误可能在构造或请求计划时暴露，不能一概推迟到 action。')
q('optimized','谓词位置变了，先看结果语义','优化前有 Project 和 Filter，优化后部分表达式已合并。','# 教学情境：优化计划与原写法不逐行对应。','哪个判断可靠？',['优化器必须保持查询语义','优化器可以随意少算几行','节点少就保证更快'],0,['对，规则变换应保持语义。','那会破坏查询正确性。','成本还取决于数据与执行。'],'优化计划可以重写表达式与关系结构，不能把计划当作用户代码逐行执行记录。','有非确定性、NULL 或类型转换时更需谨慎分析等价性。')

lesson('l4-explain-api','选对解释模式，不被长计划淹没','根据问题选择 extended、formatted、cost 与 codegen。','explain 通常不执行完整查询来返回数据，但会分析计划；cost 的统计可能缺失或估计不准。各模式与实际输出随版本变化。','sql-ref-syntax-qry-explain.html')
