follow(t,'unmatched-transfer','匹配失败也有业务贡献','# 5 元订单匹配 A，7 元订单未匹配，约定保留后者为 unknown。','应交付什么？',['A=12','A=5，unknown=7','只有 A=5'],1,['把未知误归属。','对，贡献保留且来源明确。','漏算了业务事实。'],'# LEFT JOIN 后直接 WHERE dim.label IS NOT NULL。','可能违反什么？',['保留未匹配事实的要求','自动增加分区的要求','Python 变量长度要求'],0,'连接后过滤右侧空值可能把原本应保留的未匹配事实再次排除。')
q('null-key','两个缺失用户号是否应该互配','契约规定普通等值连接，事实 NULL 用户号应视为未知。','ON fact.user_id = dim.user_id','维表也有 NULL 时应怎样处理？',['自动将所有缺失键互配','仍按普通等值语义，不互配 NULL','把用户号都改为字符串 NULL'],1,['会改变普通等值语义并可能放大。','对，按契约处理未知。','伪造相同键会改变匹配。'],'NULL 键语义是正确性约定的一部分，不应为了匹配率随意改变。','若业务另需空安全相等，应显式设计并核对基数。')
q('strategy','结果对了，再验证广播建议','维表经验证足够小，准备测试广播。','# 对照：无 hint 与 broadcast(dim)。','需要保留哪些证据？',['实际计划、构建侧、结果与资源测量条件','只保存 hint 源码','固定宣称减少两次 Shuffle'],0,['对，实施与收益分别核对。','源码不证明采用或安全。','交换次数不能无条件承诺。'],'正确连接与可审查策略证据共同构成实作交付。','本机小规模结果不等于生产内存或性能认证。')
q('accept','换输入后还能交付吗','验收还会加入新用户、未匹配订单与重复维表键。','# 目标：明确契约、稳定指标与冲突处理。','哪种实现可靠？',['把原样例结果写死','按传入数据计算并拒绝契约冲突','只在原数据上看 show'],1,['更换输入会失效。','对，行为要覆盖正常与异常输入。','样本展示不足以证明规则。'],'毕业任务应验证输入变化、空输入和契约异常，并记录未验证的运行边界。','结果验收不是防作弊或生产能力认证。')

# Deterministic option order, stable choice identity, no uniform correct position.
for index,t in enumerate(t for l in lessons.values() for t in l['tasks']):
    # Do not reorder the five existing Shuffle questions.
    if not t['id'].startswith(('l4-','l5-','l6-')):
        continue
    field=t['fields'][0];answer=next(o for o in field['options'] if o['id']==field['correctOptionId'])
    others=[o for o in field['options'] if o['id']!=field['correctOptionId']];others.insert(index%3,answer);field['options']=others
for index,t in enumerate(t for l in lessons.values() for t in l['tasks'] if t.get('remediation')):
    field=t['remediation']['field'];answer=next(o for o in field['options'] if o['id']==field['correctOptionId'])
    others=[o for o in field['options'] if o['id']!=field['correctOptionId']];others.insert((index+1)%3,answer);field['options']=others
GUIDES['version']=max(GUIDES['version'],3);DELAYED['version']=max(DELAYED['version'],3)
DELAYED['items'].sort(key=lambda item:(item['slug'],item['id']))
outputs={ROOT/'lessons'/f'{slug}.json':data for slug,data in lessons.items()}
outputs[ROOT/'standardGuides.json']=GUIDES;outputs[ROOT/'delayedChecks.json']=DELAYED
for path,data in outputs.items():
    rendered=json.dumps(data,ensure_ascii=False,indent=2)+'\n'
    if '--check' in sys.argv:assert path.read_text(encoding='utf-8')==rendered, str(path)
    else:path.write_text(rendered,encoding='utf-8')
print('PASS L4-L6:',len(lessons),'lessons,',sum(len(l['tasks']) for l in lessons.values()),'steps; existing Shuffle retained')
